function budget(pods, poolPerPod, replicas, maxConn, reserved) {
  const demanded = pods * poolPerPod * replicas;
  const usable = maxConn - reserved;
  const fits = demanded <= usable;
  const maxPool = Math.floor(usable / (pods * replicas));
  return { demanded, usable, fits, maxPool };
}

const scenarios = [
  { name: 'baseline', pods: 1, poolPerPod: 20, replicas: 1, maxConn: 100, reserved: 10 },
  { name: 'autoscaled', pods: 50, poolPerPod: 20, replicas: 1, maxConn: 100, reserved: 10 },
  { name: 'multi-replica', pods: 20, poolPerPod: 20, replicas: 2, maxConn: 100, reserved: 10 },
];

for (const s of scenarios) {
  const r = budget(s.pods, s.poolPerPod, s.replicas, s.maxConn, s.reserved);
  console.log(s.name + ': demanded=' + r.demanded + ' usable=' + r.usable + ' fits=' + r.fits + ' maxPool=' + r.maxPool);
}

