function buildPool() {
  // size to the box's CPUs — bigger boxes, bigger pool
  const poolSize = os.cpus().length * 4;
  return new Pool({
    max: poolSize,
    connectionString: process.env.DATABASE_URL,   // direct to Postgres
    // no connectionTimeoutMillis set
  });
}
